        new Quote { Id = "https://pt.wikiquote.org/wiki/Philip_Edward_Wilson", Text = "È uma honra receber a confiança de meus irmãos Bispos, rezo para que nestes tempos de desafios, a Igreja católica na Austrália continue a ser testemunha viva do Evangelho de Jesus Cristo", Author = "Philip Edward Wilson" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_Jennings_Bryan", Text = "Você não pode julgar um homem pela vida de sucesso até um momento, até a vitória de uma hora, ou até mesmo pelos resultados de um ano. Você deverá ver a sua vida como um todo.", Author = "William Jennings Bryan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Autismo", Text = "Como aprendemos mais sobre autismo, e como nossas crianças envelhecem, achamos que nós como pais e nossas crianças necessitam essa mesma alta qualidade e recursos progressivos além do objetivo do Programa de Promessa. O Centro de Kelberman cumpre essa necessidade.", Author = "Autismo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carol_Dartora", Text = "Eu acredito que a raça estrutura, nossas cidades são estruturadas na questão de raça.", Author = "Carol Dartora" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Guilherme_Weber", Text = "Estou aceitando currículos. Sério. Quero mudar meu estado civil, quero muito ser pai.", Author = "Guilherme Weber" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ep%C3%ADstola_aos_Hebreus", Text = "Deus, tendo falado outrora muitas vezes e de muitos modos a nossos pais pelos profetas, nestes dias, que são os últimos, falou-nos por meio de seu Filho, a quem constituiu herdeiro de tudo, por quem criou o mundo.", Author = "Epístola aos Hebreus" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Maria_Alice_Vergueiro", Text = "Eu me sinto uma musa cult", Author = "Maria Alice Vergueiro" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Michel_Sabbah", Text = "Diante do conflito em andamento, os cristãos não podem permanecer espectadores, mas devem trabalhar pela paz inclusive com uma resistência não violenta.", Author = "Michel Sabbah" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Joaquim_Giovanni_Mol_Guimar%C3%A3es", Text = "A Igreja pode melhorar. O ser humano pode melhorar. A sociedade pode melhorar. Poderão também se recusar a melhorar. Sair desta crise tão abrangente, geradora de tantos sofrimentos, deve nos fazer melhores.", Author = "Joaquim Giovanni Mol Guimarães" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Brock_Chisholm", Text = "O mundo estava doente, e os males dos quais ele estava sofrendo eram principalmente devido à perversão do homem, sua incapacidade de viver em paz consigo mesmo.", Author = "Brock Chisholm" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Lucia_Santaella", Text = "A hibridização de tecnologias e linguagens vem sendo chamada de convergência das mídias.", Author = "Lucia Santaella" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Fran%C3%A7ois_de_La_Rochefoucauld", Text = "A verdadeira coragem está em fazermos sem testemunha o que seríamos capazes de fazer diante de todo mundo.", Author = "François de La Rochefoucauld" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_J._Bennett", Text = "A felicidade é como um gato. Se você tentar atraí-lo ou chamá-lo, ele irá evitá-lo. Ele não virá. Mas se você não prestar atenção nele e continuar seus afazeres, você o encontrar se esfregando nas suas pernas e pulando no seu colo.", Author = "William J. Bennett" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Retiro_dos_Artistas", Text = "Sempre tive uma obsessão especial por uma vida frugal, simples e suficiente, uma vida mais comunitária e menos competitiva como aquela que a gente encontra na cidade, na zona sul. Vir para cá foi a coisa mais sábia que já fiz.", Author = "Retiro dos Artistas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jessie_J", Text = "Sim, eu namorei meninas e eu também namorei meninos. Mas não tem nada demais. Não é um segredo… Eu nunca neguei isso", Author = "Jessie J" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Blaise_Cendrars", Text = "Escrever é uma percepção do espírito. É um trabalho ingrato que leva à solidão.", Author = "Blaise Cendrars" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Eug%C3%A8ne_Lambert_Adrian_Rixen", Text = "Não podemos aceitar um projeto catequético que não parta da Bíblia e que não conduza a ela.", Author = "Eugène Lambert Adrian Rixen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Arthur_Helps", Text = "Às vezes a leitura é um modo engenhoso de evitar o pensamento.", Author = "Arthur Helps" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Luiz_Bertanha", Text = "O Espírito Santo provoca nos corações e na mente das pessoas a graça de perdoar, para também sermos perdoados. O mundo de hoje é revestido de violência, ódio, rancor, mágoa, guerras e divisões. É porque nós não sabemos perdoar. Onde está o Espírito Santo, acontece o perdão", Author = "José Luiz Bertanha" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alfred_Whitney_Griswold", Text = "Os livros não ficarão banidos. Não queimarão. As ideias não irão para a prisão. No decorrer da história, o censurador e inquisidor sempre perderam. A única arma boa contra ideias ruins, são ideias melhores.", Author = "Alfred Whitney Griswold" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/I_Macabeus", Text = "Todos os que esperam em Deus não desfalecem.", Author = "I Macabeus" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luciano_Burti", Text = "O piloto é muito egoísta. Se eu lembrasse dos meus filhos quando estou no carro, desceria na volta seguinte e nunca mais entraria.", Author = "Luciano Burti" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Bernard_Lahire", Text = "Somos multideterminados por todas as nossas experiências sociais.", Author = "Bernard Lahire" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Bruno_Musar%C3%B2", Text = "Mas estamos nas mãos de Deus. Em qualquer lugar que seja – como nos ensina o atentado em Estocolmo – devemos aprender a conviver com a ameaça terrorista.", Author = "Bruno Musarò" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_Rathje", Text = "A redução na fonte está ligado ao lixo, assim como a medicina preventiva é ligada à saúde.", Author = "William Rathje" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mestre_Eckhart", Text = "Quem quiser existir na nudez de sua natureza, livre de toda mediação, deve ter deixado atrás de si toda distinção de pessoa, de forma que seja tão aberto àquele que está longínquo, e a quem nunca tenha visto, quanto à pessoa com a qual se encontra agora, e de quem seja amigo pessoal.", Author = "Mestre Eckhart" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Albert_Kesselring", Text = "O primeiro dever de um soldado é obedecer, caso contrário, você também pode acabar com o soldado.", Author = "Albert Kesselring" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Dr._Seuss", Text = "Se você tem cérebro e sapatos nos pés, e o caminho não for agradável, vá por outro que julgar melhor.", Author = "Dr. Seuss" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alcivan_Tadeus_Gomes_de_Ara%C3%BAjo", Text = "Entendo que o episcopado não é uma promoção, e muito menos ascensão eclesiástica em busca de fama, prestigio e poder, mas serviço ao povo de Deus.", Author = "Alcivan Tadeus Gomes de Araújo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Edward_Earle_Purinton", Text = "O caráter é um triunfo de nossa determinação sobre a nossa inclinação.", Author = "Edward Earle Purinton" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Emil_Shimoun_Nona", Text = "É muito difícil saber como será o futuro dos cristãos no Iraque, mas, como cristão, espero que seja bom, embora haja muitos fatores negativos na situação atual de toda a região.", Author = "Emil Shimoun Nona" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Michael_Francis_Burbidge", Text = "Há um preço a pagar quando a verdade é defendida. Mas, como católicos, não podemos fugir dessa verdade.", Author = "Michael Francis Burbidge" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Charles_Beresford%2C_1.%C2%BA_Bar%C3%A3o_Beresford", Text = "Sinto muito não poder vir. A mentira segue pelo correio.", Author = "Charles Beresford, 1.º Barão Beresford" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Liliana_Negre_de_Alonso", Text = "Não podemos pregar que defendemos os direitos humanos, se não defendemos o primeiro deles que é o Direito à Vida.", Author = "Liliana Negre de Alonso" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Fran%C3%A7ois_Villon", Text = "Conheço tudo, exceto a mim próprio.", Author = "François Villon" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ernesto_Ara%C3%BAjo", Text = "Talvez Heidegger mudasse de opinião após ouvir o discurso de Trump em Varsóvia, e observasse: Nur noch Trump kann das Abendland retten, somente Trump pode ainda salvar o Ocidente.", Author = "Ernesto Araújo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luis_Jos%C3%A9_Rueda_Aparicio", Text = "Muitas pessoas vieram a Bogotá em busca de paz. Bogotá tem que ser uma cidade de Deus. E se é uma cidade de Deus, deve ser uma cidade da compaixão, da cultura da compaixão, da cultura da misericórdia, da clemência, da bondade.", Author = "Luis José Rueda Aparicio" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/John_Archibald_Wheeler", Text = "Algumas pessoas pensam que Wheeler ficou louco em seus últimos anos, mas ele sempre foi louco.", Author = "John Archibald Wheeler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luizianne_Lins", Text = "Se o partido não atrapalhar, já é alguma coisa.", Author = "Luizianne Lins" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Octave_Feuillet", Text = "A esperança é como o céu noturno: não há recanto tão escuro onde um olhar que se obstina não acabe por descobrir uma estrela.", Author = "Octave Feuillet" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ep%C3%ADstola_aos_Romanos", Text = "A todos os que estão em Roma, queridos de Deus, chamados a serem santos: a vós, graça e paz da parte de Deus, nosso Pai, e da parte do Senhor Jesus Cristo! Primeiramente, dou graças a meu Deus, por meio de Jesus Cristo, por todos vós, porque em todo o mundo é preconizada a vossa fé.", Author = "Epístola aos Romanos" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Le%C3%A3o_X", Text = "Se nós fizemos trinta poderemos fazer trinta e um.", Author = "Leão X" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Soninha_Francine", Text = "Fui para o budismo porque tinha a tentação de dar um soco em alguém", Author = "Soninha Francine" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Wernher_von_Braun", Text = "Nosso sol é uma entre 100 bilhões estrelas na galáxia. É muita presunção achar que seríamos os únicos seres do Universo.", Author = "Wernher von Braun" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gritos_de_torcidas", Text = "Sou brasileiro, com muito orgulho, com muito amor. ~ Torcida brasileira", Author = "Gritos de torcidas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Car%C3%A1ter", Text = "Difícil pensar em pior caráter que o do bajulador, exceto quem o inveja.", Author = "Caráter" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Tallulah_Bankhead", Text = "Jamais me alimento com o estômago vazio.", Author = "Tallulah Bankhead" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_Faulkner", Text = "Ele supunha que era à solidão que tentava escapar, e não a si mesmo.", Author = "William Faulkner" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Maur%C3%ADlio_Jorge_Quintal_de_Gouveia", Text = "Ele gostava imenso do contacto direto com as populações e por onde passava transmitia a sua alegria e cativava a atenção das pessoas.", Author = "Maurílio Jorge Quintal de Gouveia" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Erich_Fromm", Text = "O nacionalismo é a nossa forma de incesto, é a nossa idolatria, é a nossa insanidade. Patriotismo é o seu culto.", Author = "Erich Fromm" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_Hague", Text = "Precisamos fazer mais para apoiar a oposição.[...] No Reino Unido, nós estamos aumentando a assistência humanitária, estamos a enviar carregamentos de armadura, veículos à prova de balas, equipamentos de comunicação e outros meios de salvar vidas.", Author = "William Hague" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Moacir_Aparecido_de_Freitas", Text = "Estamos aqui porque cultivamos na nossa vida a oração, e queremos aprender com Jesus a rezar de modo agradável a Deus. O próprio Jesus é o mestre da oração.", Author = "Moacir Aparecido de Freitas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Sensualidade", Text = "A sensualidade é inocente, quando não está em conflito com suas obrigações.", Author = "Sensualidade" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jasmin_St._Claire", Text = "Pessoas na indústria pornô são estúpidas e sem educação, não tem nada em comum comigo. Têm uma mente pequena e limitada. Eu estudo, viajo, falo diversas linguas, me dou bem com todo mundo, tenho cultura.", Author = "Jasmin St. Claire" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jerome_Edward_Listecki", Text = "Ao sermos confrontados com o choque e a dor de nossos irmãos e irmãs em Waukesha, é importante que voltemos à nossa fé que nos oferece a presença amorosa de Deus e sua consolação.", Author = "Jerome Edward Listecki" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Leandro_Maria_Alves", Text = "Estou como todos vocês e torno-me assim parte de família. Por isso, digo chamamento sim ao de Deus.", Author = "Leandro Maria Alves" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Owen_Lovejoy", Text = "Ninguém pode me intimidar.", Author = "Owen Lovejoy" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "A razão se repete: vaidade das vaidades e toda vaidade! E a imaginação responde: plenitude de plenitude, e toda plenitude! E assim vivemos a vaidade da plenitude, ou a plenitude da vaidade.", Author = "Miguel de Unamuno" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luz_Valente_Pereira", Text = "Não há receita para se fazer cidade. Uma cidade é um processo de desenvolvimento. Uma cidade não é um edifício, obra acabada. A cidade é sempre uma obra inacabada. Como não há receita plausível, o que se pode fazer é organizar conceitos e métodos que auxiliem os projetistas urbanos.", Author = "Luz Valente Pereira" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Thomas_John_Joseph_Paprocki", Text = "Um leigo deve se dirigir somente a Deus, pois pode se envolver em problemas falando com o demônio.", Author = "Thomas John Joseph Paprocki" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Naum_Alves_de_Souza", Text = "Minhas peças tentam abordar minhas impressões a respeito de um mundo que conheço bem. Não estou fora. Estou falando de dentro.", Author = "Naum Alves de Souza" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Armando_Bucciol", Text = "Quem preside deve preparar e adaptar as dinâmicas propostas à sua situação, não simplificando para acelerar, mas aproveitando ao máximo para favorecer o êxito melhor em todos os que participam da celebração.", Author = "Armando Bucciol" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Catherine_Zeta-Jones", Text = "Eu não tenho problemas com meu corpo.", Author = "Catherine Zeta-Jones" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/John_Pilger", Text = "Putin é o único líder a condenar a ascensão do fascismo na Europa do século XXI.", Author = "John Pilger" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/St%C3%A9phane_Courtois", Text = "O filho do kulak ucraniano deliberadamente morto de fome pelo regime estalinista não é menos importante do que a criança judia do gueto de Varsóvia morta de fome pelo regime nazista.", Author = "Stéphane Courtois" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Cauby_Peixoto", Text = "Nós somos diferentes.", Author = "Cauby Peixoto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ivan_Bagramyan", Text = "O que há de errado na minha biografia? Meu pai era um trabalhador, meus irmãos também, e eu sempre servi honestamente ao meu país.", Author = "Ivan Bagramyan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ney_Latorraca", Text = "Já dei beijos ótimos até no Tarcísio Meira.", Author = "Ney Latorraca" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Robert_John_Brennan", Text = "O roubo desse item histórico não roubou a fé das pessoas desta paróquia.", Author = "Robert John Brennan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anwar_Sadat", Text = "A paz é mais importante que qualquer porção de terra.", Author = "Anwar Sadat" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Denilson_Geraldo", Text = "A escola deve ser, portanto, o primeiro ambiente social depois do ambiente familiar, onde a pessoa vive uma experiência positiva das relações sociais e fraternas, como condição para se tornarem pessoas capazes de contribuir com uma sociedade baseada na justiça e na solidariedade.", Author = "Denilson Geraldo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/C%C3%A9u", Text = "Se o céu vos atira uma tâmara, abri a boca.", Author = "Céu" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Luis_Redrado_Marchite", Text = "Pensar viver em uma sociedade livre da droga exige dos Estados a forte vontade política de extirpar definitivamente este fenômeno que alguns consideram uma realidade que já forma parte de nosso viver cotidiano e para a que simplesmente se poderiam limitar os danos.", Author = "José Luis Redrado Marchite" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Pierre_Nguy%E1%BB%85n_V%C4%83n_Nh%C6%A1n", Text = "Estamos conscientes de que a Boa Notícia foi semeada pelos missionários nos séculos passados e que a nossa Igreja nasceu do sangue dos nossos antigos mártires. Hoje queremos ser dignos da graça das nossas origens.", Author = "Pierre Nguyễn Văn Nhơn" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Drew_Barrymore", Text = "Quando meus peitos caírem até o chão e eu não puder mais ficar à frente das câmeras, adoraria produzir e dirigir.", Author = "Drew Barrymore" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Josif_Printezis", Text = "A Igreja católica aqui é pequena e é impossível acolher a todos. Por isso, estamos aqui para rezar juntos.", Author = "Josif Printezis" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Wesley_Snipes", Text = "Sabe, se eu tivesse entendido o potencial de... fazer ou adaptar personagens de quadrinhos para filmes, e também o empate em jogos e tecnologia digital, quando eu estava fazendo os primeiros filmes da Blade, então estaria dentro Um negócio diferente agora. Eu estaria em um jogo de bola diferente.", Author = "Wesley Snipes" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Paula_Toller", Text = "Moro na Barra da Tijuca e estou com medo de voltar pra casa", Author = "Paula Toller" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Andr%C3%A9s_Vargas_Pe%C3%B1a", Text = "Irei ao local do acidente para rezar pelos que ali morreram e para expressar aos familiares o abraço maternal da Igreja.", Author = "Andrés Vargas Peña" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Fran%C3%A7ois-Andr%C3%A9_Danican_Philidor", Text = "Os Peões são as almas do Xadrez.", Author = "François-André Danican Philidor" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Z%C3%B3zimo_Barrozo_do_Amaral", Text = "O real está precisando urgentemente de um exame de DNA.", Author = "Zózimo Barrozo do Amaral" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Frank_Herbert", Text = "O início do conhecimento é a descoberta de qualquer coisa que não entendemos.", Author = "Frank Herbert" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Raymond_Cent%C3%A8ne", Text = "Mesmo que os pensadores livres queiram ou não, o cristianismo faz parte da nossa identidade europeia. O cristianismo é mais do que uma religião, é constitutivo do nosso ser, do nosso modo de viver e da nossa forma de entender os problemas de convivência.", Author = "Raymond Centène" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Nazarene_Soosai", Text = "É uma grande honra e orgulho para o povo indiano, mas acima de tudo para o povo do sul da Índia, onde o mártir Devasahayam Pillai é venerado. Ele já é um Santo para nós no sul. Esperamos que a Santa Sé anuncie a data em que será elevado à honra dos altares.", Author = "Nazarene Soosai" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jay_Leno", Text = "O último boato é que Monica Lewinsky teve uma relação imprópria com um charuto de Clinton.", Author = "Jay Leno" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Paulo_Vilhena", Text = "Quando eu me casar, juro que vou fazer o maior esforço. Mas a concorrência está cada vez mais enlouquecida. Assim fica difícil, né?", Author = "Paulo Vilhena" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Hans-Joachim_Marseille", Text = "Marseille foi o mais virtuoso, jamais igualado, entre os pilotos de caça da 2.ª Guerra Mundial. Suas conquistas eram anteriormente consideradas impossíveis e nunca foram superadas por ninguém depois de sua morte.", Author = "Hans-Joachim Marseille" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Marc_Aillet", Text = "Por-se impunemente ao plano do Criador pode causar sérios danos ao futuro da humanidade. Esta é a razão fundamental para a nossa defesa da dignidade da pessoa humana, começando pelos mais pequenos e vulneráveis", Author = "Marc Aillet" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Manuela_d%27%C3%81vila", Text = "Vamos para cima, gente, com o nosso amor, com a nossa hipocrisia", Author = "Manuela d'Ávila" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Otto_Friedrich_Walter", Text = "O acaso é a lógica de Deus.", Author = "Otto Friedrich Walter" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anatoly_Karpov", Text = "Xadrez é tudo - arte, ciência e esporte.", Author = "Anatoly Karpov" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/%C3%89douard_Herriot", Text = "Cultura é o que fica depois de se esquecer tudo o que foi aprendido.", Author = "Édouard Herriot" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Marshall", Text = "Não lute contra o problema; resolva-o", Author = "George Marshall" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gerrit_Achterberg", Text = "Ja, maar niet te veel.", Author = "Gerrit Achterberg" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_Slim%2C_1.%C2%BA_Visconde_Slim", Text = "Não há maus regimentos, há apenas maus oficiais.", Author = "William Slim, 1.º Visconde Slim" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Maurice_Anthony_Crowley", Text = "Nenhum jovem deve ser excluído da escola pública por não pagar as taxas.", Author = "Maurice Anthony Crowley" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Percy_Lorenzo_Galv%C3%A1n_Flores", Text = "Nosso serviço deve ser apostólico, ou seja, deve ser feito em nome de Deus, não para nos fazer sentir bem a nós mesmos.", Author = "Percy Lorenzo Galván Flores" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Deborah_Kerr", Text = "Aí a cena nu era necessária, marido e mulher na cama juntos.", Author = "Deborah Kerr" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Vicky_Hartzler", Text = "É realmente uma violação dos direitos humanos no mais alto nível.", Author = "Vicky Hartzler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Witness_Lee", Text = "Cada ser humano é uma totalidade da vida humana.", Author = "Witness Lee" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Opilio_Rossi", Text = "Estava persuadido de que os jovens deviam aprender da história do século XX uma importante lição: ou seja, que do ódio, do desprezo do próximo, da violência, do nacionalismo exacerbado, surgem apenas lágrimas e sangue.", Author = "Opilio Rossi" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Bruno_Geddo", Text = "O Estado Islâmico conhece as rotas para sair da cidade e vai matar as pessoas que estiverem fugindo, afirma Geddo. Há apenas uma estreita rota segura. Se muitas pessoas tentarem usá-la, haverá gargalos, que são sempre perigosos. Eles são fáceis de atacar.", Author = "Bruno Geddo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Theresa_Amayo", Text = "Eu sofri, as mães das minhas colegas começaram a proibir que as meninas fossem minhas amigas porque agora eu não era mais uma menina respeitável, eu era uma atriz, então foram dores que eu fui sofrendo, e adolescente ainda", Author = "Theresa Amayo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Kate_Sheppard", Text = "Tudo o que separa, seja de raça, classe, credo ou sexo, é desumano e precisa ser superado.", Author = "Kate Sheppard" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Victor_Civita", Text = "NÃO é a mais fácil e cômoda palavra que existe. Se alguém diz não, os problemas acabaram. Os problemas realmente começam quando você diz SIM.", Author = "Victor Civita" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anne_Morrow_Lindbergh", Text = "Pessoas demais, exigências demais, muito a fazer; pessoas competentes, ocupadas, apressadas - isso não é viver.", Author = "Anne Morrow Lindbergh" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Supersti%C3%A7%C3%A3o", Text = "A superstição ofende mais a Deus do que o ateísmo.", Author = "Superstição" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Dogen", Text = "Mas não me pergunte para onde estou indo, Pois viajo neste mundo ilimitado, Onde cada passo que eu dou é minha casa.", Author = "Dogen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/%C3%89mile_Henriot", Text = "A cultura é aquilo que permanece no homem quando ele já esqueceu tudo o resto.", Author = "Émile Henriot" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Georges_Varkey_Puthiyakulangara", Text = "As pessoas vêm do exterior, não sabemos como, e também há recrutamento dentro do país. Somos confrontados com a islamização do país.", Author = "Georges Varkey Puthiyakulangara" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Tarja_Turunen", Text = "Eu fiquei imediatamente impressionado, porque sua voz é perfeitamente limpa.", Author = "Tarja Turunen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Erma_Bombeck", Text = "Qualquer um que assista a três jogos de futebol americano seguidamente deveria ser considerado com morte cerebral.", Author = "Erma Bombeck" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Baselios_Cleemis_Thottunkal", Text = "A Índia tem de se preocupar em primeiro lugar com os direitos humanos, com a dignidade de homens e mulheres e com o bem-estar de seu povo e não com as vacas", Author = "Baselios Cleemis Thottunkal" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Natale_Paganelli", Text = "Há aqueles que querem a África pobre e aqueles que querem a corrupção, porque desta forma eles controlam os minerais. É preciso estar vigilante", Author = "Natale Paganelli" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Div%C3%B3rcio", Text = "Mulher finge bem, casar é negócio você vê quem é quem, só depois do divórcio.", Author = "Divórcio" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carol_Narizinho", Text = "Ah, na adolescência, eu era bem magrinha, não tinha peito, não tinha bunda. Era meio um bichinho da goiaba. E eu era apaixonada por um menino que me esnobava e me achava feia.", Author = "Carol Narizinho" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Blake", Text = "Foi o bombardeio implacável de pequenas aldeias coreanas por enormes fortalezas voadoras americanas. Mulheres, crianças e idosos, porque os jovens estavam no exército.", Author = "George Blake" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Randy_Pausch", Text = "Nós não podemos mudar as cartas que nos foram dadas, mas apenas o modo como iremos jogá-las. Se eu não estou tão deprimido ou triste como deveria estar, desculpe desapontá-los.", Author = "Randy Pausch" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Leonid_Kravchuk", Text = "Eu estou perfeitamente de acordo de que se tratou de uma acção planeada, que foi um acto do genocídio contra o nosso próprio povo.", Author = "Leonid Kravchuk" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Paul_Simon", Text = "Quando eu estava no ensino médio, eu queria ser como Little Richard.", Author = "Paul Simon" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Marcel_Jouhandeau", Text = "É-se sempre mais religioso do que aquilo que se pensa.", Author = "Marcel Jouhandeau" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Thiago_de_Mello", Text = "Quem não sonha o azul do vôo, perde seu poder de pássaro.", Author = "Thiago de Mello" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/J%C3%B4_Soares", Text = "É uma decisão de lado a lado, e depois, a gula é um pecado (risos).", Author = "Jô Soares" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Iv%C3%A1n_Antonio_Mar%C3%ADn_L%C3%B3pez", Text = "Foi justamente a evangelização que mais contribuiu para se desenvolvimento em todos os campos. A fé não somente não os tornou escravos, mas os libertou dos medos, dos tabus, das forças mágicas a quem atribuíam todos os fenômenos naturais, para entrar na liberdade autêntica dos filhos de Deus.", Author = "Iván Antonio Marín López" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/V%C3%A1gner_Benazzi", Text = "Nosso time aprendeu jogar em casa. A torcida que comparece é para incentivar e torcer e isso nos ajuda muito. Temos que sempre pensar nos três pontos em casa, ainda mais em um campeonato tão disputado.", Author = "Vágner Benazzi" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Horst_Eberlein", Text = "Sobretudo agora, quando a pandemia de Covid-19 obscurece a visão de muitas outras coisas, o ecumenismo ajuda-nos a olhar-nos novamente reciprocamente, mostrando que nem todos rezam somente para si mesmos.", Author = "Horst Eberlein" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Rockwell_Kent", Text = "É incontestável que a arte deve conter valor social; como poderoso meio de comunicação que é, deve ser dirigida e em termos compreensíveis à percepção da humanidade.", Author = "Rockwell Kent" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Clemente_Jos%C3%A9_Carlos_de_Gouvea_Isnard", Text = "Ser bispo representou para mim uma conversão. Achei, então, que devia dar um testemunho público acerca das atuais instituições eclesiásticas.", Author = "Clemente José Carlos de Gouvea Isnard" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Juraci_Magalh%C3%A3es", Text = "Eu vou ganhar da raça lá todinha. Não tem um tucano lá que eu não serre o bico dele.", Author = "Juraci Magalhães" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Arturo_Graf", Text = "Escutai os conselhos de quem muito sabe, mas especialmente os conselhos de quem muito vos ama.", Author = "Arturo Graf" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Simone", Text = "``Eu amo a Natureza.´´", Author = "Simone" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mattoso_C%C3%A2mara", Text = "Na verdade, em nosso país, a história da Linguística não pode ser contada sem referência a, pelo menos, dois nomes (se outros forem esquecidos): Joaquim Mattoso Câmara Jr. e Aryon Dall'Igna Rodrigues.", Author = "Mattoso Câmara" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anna_Sui", Text = "Anna foi uma das designers que ajudou a definir o que hoje entendemos como a Geração X.", Author = "Anna Sui" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Primeiro_Golpe_de_Mobutu", Text = "O Exército Nacional Congolês decidiu neutralizar o Chefe de Estado, os dois governos rivais presentes, bem como as duas câmaras legislativas até 31 de dezembro. Isso permitirá que os políticos tenham tempo para tentar chegar a um acordo, a fim de melhor servir os interesses primordiais deste país.", Author = "Primeiro Golpe de Mobutu" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Tamara_Klink", Text = "Uma mulher precisa viajar. Para descobrir por si mesma aonde é capaz de chegar.", Author = "Tamara Klink" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alegria", Text = "Só temos alegrias se as repartirmos: a felicidade nasceu gémea", Author = "Alegria" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Moreira_de_Melo", Text = "As redes sociais são o fruto da interação humana, mas, por sua vez, dão formas novas às dinâmicas da comunicação que cria relações; por isso, uma solícita compreensão por este ambiente é o pré-requisito para uma presença significativa dentro dele.", Author = "José Moreira de Melo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Camila_Pitanga", Text = "Votarei de novo em Lula, mas sem a inocência de antes", Author = "Camila Pitanga" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Dmitry_Peskov", Text = "As forças da Rússia não disparam contra alvos civis.", Author = "Dmitry Peskov" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Internet", Text = "A busca da relevância gerou os gigantes da internet.", Author = "Internet" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gabriel_Narciso_Escobar_Ayala", Text = "Uma característica do povo paraguaio é resistir e sofrer, mas não se pode mais tolerar esta situação, as pessoas desta parte do país merecem uma vida melhor.", Author = "Gabriel Narciso Escobar Ayala" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Nicolau_II_da_R%C3%BAssia", Text = "Hoje eu terminei definitiva e eternamente minha educação.", Author = "Nicolau II da Rússia" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alan_Kay", Text = "A melhor maneira de predizer o futuro é inventá-lo.", Author = "Alan Kay" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Kalpana_Chawla", Text = "O caminho dos sonhos ao sucesso existe. Que vocês possam ter a visão para encontrá-lo e a coragem de entrar nele.", Author = "Kalpana Chawla" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Oliver_Cromwell", Text = "Pinta-me como sou. Se não puseres as cicatrizes nem as rugas, não te pagarei.", Author = "Oliver Cromwell" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ross_Brawn", Text = "Se olharmos os dados da telemetria em curvas rápidas, ou o seu tempo de reação nas freadas, não veremos diferença nenhuma. Ainda é o velho Michael … Mas, nas curvas lentas, ele não consegue usar os pneus do jeito que o Nico (Rosberg) consegue.", Author = "Ross Brawn" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Eike_Batista", Text = "Tive um casamento espetacular, admiro a Luma, tivemos dois filhos, que são dois diamantes. Isso é uma história de sucesso. Eu me sinto parcialmente culpado pelo fim porque trabalho demais", Author = "Eike Batista" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Le_Corbusier", Text = "A arquitetura é o jogo sábio, correto e magnífico dos volumes dispostos sob a luz.", Author = "Le Corbusier" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Greg_Walden", Text = "Eu estou aberto à escuta todos os lados nesta. Nós queremos certificar-se que os doutores estão compensados adequadamente.", Author = "Greg Walden" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Pius_Riana_Prapdi", Text = "Hoje, as diferenças e as diversidades das nações asiáticas são um bem que somos chamados a descobrir. Através do encontro, esperamos que os jovens provenientes de diversos países possam compartilhar experiências, reflexões e intuições de fé, a fim de reforçar a sua confiança em um futuro melhor.", Author = "Pius Riana Prapdi" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/El%C3%ADas_Yanes_%C3%81lvarez", Text = "Certamente, exista uma corrente de pensamento que gostaria que a Igreja Católica deixasse de ser católica, ou como se os bispos não fôssemos. A Igreja tem que ser fiel aos elementos essenciais, tal como a constituiu Jesus Cristo.", Author = "Elías Yanes Álvarez" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/The_Simpsons", Text = "Ah,eu tenho três filhos e nenhum dinheiro.Por que eu não posso ter nenhum filho e três dinheiros?", Author = "The Simpsons" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Petr%C3%B4nio", Text = "Mundus vult decipi, ergo decipiatur.", Author = "Petrônio" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Marlene_Mattos", Text = "Não gosto de gente burra e puxa-saco", Author = "Marlene Mattos" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Cristiana_Oliveira", Text = "Eu emburreci fazendo tevê. A televisão é algo que me consome demais.", Author = "Cristiana Oliveira" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Otto_Skorzeny", Text = "Duce, o Führer me enviou para libertá-lo!", Author = "Otto Skorzeny" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gilbert_Murray", Text = "A vida, a liberdade e a felicidade do homem comum, em toda parte do mundo, estão à mercê absoluta de umas poucas pessoas, as quais ele nunca viu, envolvidas em complicadas querelas, sobre as quais ele nunca ouviu falar.", Author = "Gilbert Murray" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Lauren_Boebert", Text = "Os EUA financiaram pesquisas de ganho de função em Wuhan. Fauci mentiu.", Author = "Lauren Boebert" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Iron_Maiden", Text = "É como aula de aeróbica. Não que eu já tenha feito uma, mas deve ser a mesma coisa", Author = "Iron Maiden" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Zibia_Gasparetto", Text = "Ninguém é prejudicado a não ser por si mesmo, ninguém fecha a porta à felicidade ou abre ao sofrimento a não ser por si mesmo. Até aí eu vou, posso entender que somos responsáveis por nosso destino.", Author = "Zibia Gasparetto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Auguste_Perret", Text = "É preciso fazer cantar o ponto de apoio.", Author = "Auguste Perret" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Dora_Russell", Text = "Leis do casamento, polícia, exércitos e forças armadas são evidências da incompetência humana.", Author = "Dora Russell" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Wilhelm_Bittrich", Text = "Em todos os meus anos como soldado, nunca vi homens lutarem tanto.", Author = "Wilhelm Bittrich" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Oskar_Schindler", Text = "Eu conhecia as pessoas que trabalhavam para mim. Quando você conhece pessoas, você tem que se comportar em relação a elas como seres humanos.", Author = "Oskar Schindler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Rodrigo_Aguilar_Mart%C3%ADnez", Text = "O mundo não nos leva hoje a cultivar a misericórdia, pelo contrário, nos leva a ser juízes e executores enérgicos, de modo que a violência é resolvida com uma ação mais violenta, e isso é arrogância, prepotência. Assim, com estes critérios, o mundo de ser humano está se tornando selvagem.", Author = "Rodrigo Aguilar Martínez" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Donald_Francis_Lippert", Text = "Não é possível controlar as crenças das pessoas, mas é possível controlar as suas ações. Os ataques a pessoas suspeitadas de praticar magia negra serão detidos somente quando os autores forem condenados.", Author = "Donald Francis Lippert" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ashley_Montagu", Text = "A ciência tem provas sem certeza. Os teólogos têm certeza sem qualquer prova.", Author = "Ashley Montagu" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Pierre_Beaumarchais", Text = "Tudo acaba em canções.", Author = "Pierre Beaumarchais" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/James_Bryant_Conant", Text = "Aquele que entra em uma universidade caminha em solo sagrado.", Author = "James Bryant Conant" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Isaac_Rosenberg", Text = "Eu nunca entrei para o exército por razões patrióticas.", Author = "Isaac Rosenberg" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Eddie_Murphy", Text = "Este é meu ídolo, Elvis Presley. Ele é o maior artista que já existiu. Acredito que é por causa de sua presença. Quando Elvis Presley entrava na sala, Elvis Presley entrava na sala. Não interessa quem estava na sala, Bogart, Marilyn Monroe.", Author = "Eddie Murphy" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alfred_M._Gray_Jr.", Text = "Todo fuzileiro naval é, antes de tudo, um atirador. Todas as outras condições são secundárias", Author = "Alfred M. Gray Jr." },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Kate_Winslet", Text = "Quando você acorda de manhã e sabe que está indo para o trabalho, onde vai tirar a roupa, isso é como se fosse o pior dia de sua vida. Você se sente péssima, enjoada. Depois, você chega a cogitar a hipótese de nunca mais fazer isso de novo.", Author = "Kate Winslet" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alexandria_Ocasio-Cortez", Text = "AOC é a Perón dos Estados Unidos.", Author = "Alexandria Ocasio-Cortez" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Jellinek", Text = "O Direito não é nada além do mínimo ético.", Author = "George Jellinek" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Romain_Rolland", Text = "Quando a ordem é injusta, a desordem é já um princípio de justiça.", Author = "Romain Rolland" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/T._S._Eliot", Text = "O que poderia ter sido e o que foi convergem para um só fim, que é sempre presente.", Author = "T. S. Eliot" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Joaquim_Nabuco", Text = "Alguma coisa observei no estudo do nosso passado, é quanto são fúteis as nossas tentativas para deprimir(-lo)", Author = "Joaquim Nabuco" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/James_Watson", Text = "Como a mente funciona ainda é um mistério. Nós entendemos o hardware, mas não temos a menor idéia sobre o sistema operacional.", Author = "James Watson" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Henry_Sidgwick", Text = "O bem de qualquer indivíduo não tem mais importância, do ponto de vista... do Universo, do que o bem de qualquer outro; isto é, a menos que haja motivos especiais para acreditar que é provável que se realize mais bem num caso do que no outro.", Author = "Henry Sidgwick" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Paolo_Rudelli", Text = "Não há outro caminho senão o diálogo e o confronto entre as diferentes e às vezes opostas antropologias, no qual o cristão tem algo original a dizer.", Author = "Paolo Rudelli" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/James_Newland", Text = "Pela mais evidente bravura e dedicação ao dever, diante de grandes probabilidades, em três ocasiões distintas.", Author = "James Newland" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Conflito", Text = "As dificuldades devem ser usadas para crescer, não para desencorajar. O espírito humano cresce mais forte no conflito.", Author = "Conflito" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/E%C3%A7a_de_Queiroz", Text = "Com o fisco, paga-se sempre e nunca se questiona, porque naturalmente depois é-se obrigado a pagar mais.", Author = "Eça de Queiroz" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ricardo_Noblat", Text = "O papel aceita qualquer coisa. O computador também. Temos que ser maduros na hora de escrever os relatos de todos os dias.", Author = "Ricardo Noblat" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gabriel_Bernardo_Barba", Text = "Como Igreja, continuemos em comunhão, rezando pela paz e construindo-a.", Author = "Gabriel Bernardo Barba" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anast%C3%A1cio_Cahango", Text = "Notamos muita violência nos bairros, em grupos de jovens e os roubos aumentaram. Há também falta de compromisso dos nossos jovens nas paróquias, especialmente a um matrimónio sério. Algumas jovens vão procurar casamento noutras seitas", Author = "Anastácio Cahango" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Otis_Chandler", Text = "Quando nos preocupamos demais com o que certos grupos ou pessoas pensam de nós, arriscamos vender nossa alma nos amoldando a eles, por expediente.", Author = "Otis Chandler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Freedom_for_the_Thought_That_We_Hate", Text = "Sempre haverá autoridades que tentam tornar suas próprias vidas mais confortáveis, suprimindo comentários críticos. (...) Mas estou convencido de que o compromisso fundamental americano com a liberdade de expressão, a fala perturbadora, não está mais em dúvida.", Author = "Freedom for the Thought That We Hate" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Lea_T", Text = "Mesmo com a cirurgia, eu nunca vou ser mulher. E também não serei homem. Eu vou ser sempre o do meio", Author = "Lea T" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Giovanni_Boccaccio", Text = "Num voo de pombas brancas, um corvo negro junta-lhe um acréscimo de beleza que a candura de um cisne não traria.", Author = "Giovanni Boccaccio" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Elia_Dalla_Costa", Text = "São conhecidas as palavras do seu guia espiritual, padre Raffaele Bensi, no qual se inspiraram nestes anos as figuras mais eminentes do catolicismo florentino, tão vivo em meados do século passado, sob o paterno ministério do venerável Cardeal Elia Dalla Costa.", Author = "Elia Dalla Costa" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Hubertus_van_Megen", Text = "A única palavra que deveria ser pronunciada é a Palavra de Deus, Senhor desta Casa. Nenhum debate político, nenhum comércio, nenhuma discussão deve acontecer neste lugar.", Author = "Hubertus van Megen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Susanne_Langer", Text = "Nisto os símbolos diferem radicalmente dos sinais. Um sinal é compreendido se serve para fazer-nos notar o objeto ou situação que indica. Um símbolo é compreendido quando podemos conceber a ideia que ele apresenta.", Author = "Susanne Langer" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Camillus_Archibong_Etokudoh", Text = "Buscamos educar as pessoas como comunidade cristã, temos reuniões e momentos de oração em comum. Nesse sentido, não raciocianmos em termos de maioria ou minoria em relação às outras confissões cristãs, porque trabalhamos juntos para fazer com que todos os cristãos sejam uma coisa só.", Author = "Camillus Archibong Etokudoh" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Heinrich_Himmler", Text = "Os anseios dos nazismo e do front-vermelho são os mesmos. O judeu quis adulterar a revolução para o marxismo, e este não trouxe a satisfação, razão pela qual não está em questão hoje. Portanto, até hoje há um desejo pelo socialismo.", Author = "Heinrich Himmler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Layne_Beachley", Text = "Vou atrás daquilo que quero com força total até conseguir, se significar muito para mim.", Author = "Layne Beachley" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Olivier_Michel_Marie_Schmitthaeusler", Text = "Os jovens cambojanos sabem que são apóstolos e estão conscientes de que a evangelização não é uma prerrogativa reservada a sacerdotes e religiosos. É a esperança de Cristo em nós e que nós queremos dar ao mundo. O Evangelho não se difunde através do proselitismo, mas por contágio.", Author = "Olivier Michel Marie Schmitthaeusler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carlos_Marun", Text = "Sou autêntico. Quando estou feliz, eu canto", Author = "Carlos Marun" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Stephanie_Seymour", Text = "Eu detesto ela. Ela é a encrenca em pessoa. Falsa, não é confiável, não sabe o que é o amor ou gostar de alguém sem segundos interesses, a mãe dela já é assim.", Author = "Stephanie Seymour" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Raoul_Wallenberg", Text = "Tivemos muitas conversas longas e íntimas. Ele estava cheio de ideias e planos para o futuro.", Author = "Raoul Wallenberg" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Johann_Sebastian_Bach", Text = "Tive que trabalhar duramente. Quem trabalha assim duramente conseguirá chegar igualmente longe.", Author = "Johann Sebastian Bach" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mitchell_Ryan", Text = "Meu doce, amado amigo Mitch morreu nesta manhã.", Author = "Mitchell Ryan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Novalis", Text = "Não é apenas o conhecimento que nos faz felizes - é a qualidade do conhecimento, a natureza subjetiva do conhecimento. Conhecimento perfeito é convicção e é o que nos faz felizes e satisfatórios.", Author = "Novalis" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Tristan_Bernard", Text = "Para se ser feliz com os outros, não devemos perguntar-lhes o que têm para oferecer.", Author = "Tristan Bernard" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Tristan_Azbej", Text = "É o berço do cristianismo.", Author = "Tristan Azbej" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Beb%C3%AA", Text = "Dê a seu bebê uma alimentação à base de cebola. Assim poderá achá-lo mais facilmente no escuro.", Author = "Bebê" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Agustinus_Agus", Text = "A pandemia não conhece raça, etnia, religião, classe social ou grupo, é importante que nós - pessoas de diferentes religiões - façamos algo para ajudar os outros.", Author = "Agustinus Agus" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carl_Rowan", Text = "A biblioteca é o templo do saber, e este tem libertado mais pessoas do que todas as guerras da história.", Author = "Carl Rowan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Avenged_Sevenfold", Text = "Time still turns the pages of the book it's burned", Author = "Avenged Sevenfold" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Hezbollah", Text = "O Hezbollah não é um estado. Eles são um, você sabe, um suposto partido político que por acaso está armado.", Author = "Hezbollah" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Peter_David_Gregory_Smith", Text = "Os seres humanos têm uma só natureza, especificamente separada dos animais. Em vez de promover um tipo de pesquisa problemática eticamente, por que não se alenta a pesquisa com as células estaminais adultas que não gera controvérsias?", Author = "Peter David Gregory Smith" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jim_Morrison", Text = "Eu vejo-me como um ser humano sensível e inteligente, mas com um coração de palhaço que me obriga a estragar tudo nos momentos mais importantes.", Author = "Jim Morrison" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Harriet_Beecher_Stowe", Text = "A primeira hora da manhã é o leme do dia.", Author = "Harriet Beecher Stowe" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Giordano_Bruno", Text = "O tempo tudo tira e tudo dá; tudo se transforma, nada se destrói.", Author = "Giordano Bruno" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Miguel_Jos%C3%A9_Asurmendi_Aramend%C3%ADa", Text = "A igreja proclama o direito à vida de todo ser humano a partir do mesmo instante de sua concepção, por isso o aborto provocado é dar morte a um ser humano. O aborto é um claro sinal da crise de consciência moral em nossa sociedade.", Author = "Miguel José Asurmendi Aramendía" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Andrew_Murray_%28pastor%29", Text = "Somente Deus pode satisfazer o coração humano.", Author = "Andrew Murray (pastor)" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Presidente", Text = "Quando o presidente faz, significa que não é ilegal.", Author = "Presidente" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Lua", Text = "Quando Ismália enlouqueceu, / Pôs-se na torre a sonhar... / Viu uma lua no céu, / Viu outra lua no mar.", Author = "Lua" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Youhannes_Ezzat_Zakaria_Badir", Text = "O principal problema do Egito de hoje é a ignorância política, para a qual tudo termina por ter uma conotação religiosa. Isto é verdadeiro tanto para cristãos quanto para muçulmanos. Precisamos todos amadurecer politicamente.", Author = "Youhannes Ezzat Zakaria Badir" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Desenvolvimento_sustent%C3%A1vel", Text = "O mundo não suporta mais esse padrão de consumo.", Author = "Desenvolvimento sustentável" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ronald_Reagan", Text = "Meus caros americanos: tenho o prazer de informar que acabo de assinar uma lei que banirá a URSS para sempre. O bombardeio começa em 5 minutos.", Author = "Ronald Reagan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Sydney_Smith", Text = "Não gosto nem um pouco do campo; é uma espécie de sepultura saudável.", Author = "Sydney Smith" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Konrad_Krajewski", Text = "Em plena conformidade com as regras de segurança é meu direito assegurar aos pobres uma igreja aberta. Nesta manhã, às 8 da manhã, eu vim aqui e abri as portas. Deste modo, os pobres poderão adorar o Santíssimo Sacramento, que é o consolo para todos neste momento de grande dificuldade.", Author = "Konrad Krajewski" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/John_Casablancas", Text = "Naomi tem um lado realmente sórdido, isso por causa de seu temperamento, seu estilo de vida e sua história. Gosto bastante dela, mas não voltaria a trabalhar com Naomi nem por todo ouro do mundo", Author = "John Casablancas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anthony_Bourdain", Text = "Ter conhecimentos culinários básicos é uma virtude... a habilidade de cozinhar com segurança para si e outros deveria ser passado como sendo algo fundamental a ser aprendido por todo jovem, como o é saber se limpar após usar o banheiro, cruzar a rua sozinho ou saber lidar com dinheiro.", Author = "Anthony Bourdain" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ant%C3%B3nio_Dam%C3%A1sio", Text = "O sofrimento proporciona-nos a melhor protecção para a sobrevivência, uma vez que aumenta a probabilidade de darmos atenção aos sinais de dor e agirmos no sentido de evitar a sua origem ou corrigir as suas consequências.", Author = "António Damásio" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Cesar_Maia", Text = "Não me afogo em bidê.", Author = "Cesar Maia" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carolina_Dieckmann", Text = "Outro dia um policial me chamou e disse: você é o maior filé", Author = "Carolina Dieckmann" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Sigitas_Tamkevi%C4%8Dius", Text = "O uso de símbolos católicos para fins comerciais e especialmente para a publicidade de bebidas alcoólicas é absolutamente injustificáve.", Author = "Sigitas Tamkevičius" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Maria_Pedroto", Text = "As gentes do Porto são ordeiras porque, se não fossem, há muitos anos teriam recorrido à violência perante os enganos dos árbitros que têm decidido da perda de muitos campeonatos e Taças de Portugal.", Author = "José Maria Pedroto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Marcos_Frota", Text = "A gente passa a ver a vida com os olhos do coração", Author = "Marcos Frota" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Charles_Sanders_Peirce", Text = "Nunca estive em meu poder estudar nada, - matemática, ética, metafísica, gravitação, termodinâmica, óptica, química, anatomia comparada, astronomia, psicologia, fonética, economia, história da ciência, whist, homens e mulheres, vinho, metrologia, exceto como um estudo de semiótica.", Author = "Charles Sanders Peirce" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Werner_M%C3%B6lders", Text = "Ele era um estrategista maravilhoso. A minha admiração por ele não tinha limites. Tinha uma grande inteligência e uma grande personalidade. Foi o homem com os mais elevados princípios que alguma vez conheci.", Author = "Werner Mölders" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Juvenal", Text = "A honestidade é ser elogiado e morrer de fome.", Author = "Juvenal" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Orgulho_e_Preconceito", Text = "É uma verdade universalmente conhecida que um homem solteiro, em posse de grande fortuna, deve estar procurando uma esposa.", Author = "Orgulho e Preconceito" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Harrison_Butker", Text = "Fora das luzes brilhantes do estádio, com os fãs e a notoriedade que vem por ser um jogador da NFL, o maior impacto que vou causar com meu tempo nesta terra é permanecer dedicado à minha vocação principal: ajudar minha família a alcançar o Céu.", Author = "Harrison Butker" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Homem", Text = "No amor, as mulheres são profissionais; os homens, amadores.", Author = "Homem" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Michael_Schumacher", Text = "Se olharmos os dados da telemetria em curvas rápidas, ou o seu tempo de reação nas freadas, não veremos diferença nenhuma. Ainda é o velho Michael … Mas, nas curvas lentas, ele não consegue usar os pneus do jeito que o Nico (Rosberg) consegue", Author = "Michael Schumacher" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Sabotage_%28rapper%29", Text = "Todo bom malandro tem uma Tereza do lado!", Author = "Sabotage (rapper)" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ti%C3%A3o_Viana", Text = "País precisa de mais ministros como ele, que dignificam o Brasil.", Author = "Tião Viana" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mary_Kate_e_Ashley_Olsen", Text = "Teve momentos na minha vida que falei para as pessoas que estava cansada, que isso era demais para mim", Author = "Mary Kate e Ashley Olsen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Sebastiano_Sanguinetti", Text = "O fato que essa sociedade desapareça representa realmente uma perda cujas proporções ainda não são conhecidas e, isso, como bispo, me preocupa muito.", Author = "Sebastiano Sanguinetti" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Rocco_Siffredi", Text = "Meus filhos estão crescendo e já não posso simplesmente dizer: 'papai está indo trabalhar, sustentar a família'. Eles agora querem saber mais.", Author = "Rocco Siffredi" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Marcial", Text = "A pessoa capaz de sentir prazer com o próprio passado vive duas vezes.", Author = "Marcial" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Prov%C3%A9rbios_poloneses", Text = "Baba z wozu, koniom lżej.", Author = "Provérbios poloneses" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Emmanuel_Delmas", Text = "Que este tempo de prova seja uma oportunidade para rezar, especialmente pelos doentes, os mais frágeis e os profissionais da saúde.", Author = "Emmanuel Delmas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/L%C3%BAcio_Mauro", Text = "A gente é muito fã um do outro, o papai é muito fã meu, é mais fã do que mentor, ele gosta de me ver, me incentiva. É um pai muito apaixonado, muito coruja.", Author = "Lúcio Mauro" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Beryl_Burton", Text = "[Beryl] tinhas suas próprias ideias sobre o que ia fazer e ela fez. Nada ficou no caminho dela.", Author = "Beryl Burton" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Maom%C3%A9", Text = "O Islã foi erguido sobre cinco pilares. é prestarmos testemunho de que não existe outra divindade além de Deus, e de que Mohammad é o Seu Mensageiro; o cumprimento das orações; o pagamento do zakat; a peregrinação à Casa de Deus; e a observância do jejum no mês de Ramadan.", Author = "Maomé" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luis_Fernando_Verissimo", Text = "Ninguém é uma coisa só, nós todos somos muitos.", Author = "Luis Fernando Verissimo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Olivier_Ribadeau_Dumas", Text = "Eu acho que devemos ser prudentes e esperar para saber quem realizou este atentado. Não devemos tirar conclusões apressadas. É também preciso lembrar duas coisas essenciais. A primeira é que não devemos ceder ao ódio. A segunda é que devemos viver a fraternidade no diálogo.", Author = "Olivier Ribadeau Dumas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Celso_Martinez_Corr%C3%AAa", Text = "A cultura, e não a macroeconomia, é a infraestrutura da vida, a energia propulsora. A macroeconomia está fazendo mal à humanidade. Quando o indivíduo, por meio da cultura, desperta para a autopercepção de que é livre, na hora ele sai da miséria.", Author = "José Celso Martinez Corrêa" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Futebol", Text = "Os italianos não podem nos vencer, mas nós certamente podemos perder contra eles", Author = "Futebol" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Andrew_Tsien_Chih-ch%27un", Text = "Aposento-me, mas jamais serei preguiçoso… buscando promover a comunhão na Igreja uma, santa, católica e apostólica.", Author = "Andrew Tsien Chih-ch'un" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alfred_Tarski", Text = "Não há dúvida de que o conhecimento da lógica é de considerável importância prática para todos os que desejam pensar e inferir corretamente.", Author = "Alfred Tarski" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/William_Henry_Beveridge", Text = "O ruim da democracia moderna é que as pessoas só chegam à liderança depois de terem perdido a vontade de liderar quem quer que seja.", Author = "William Henry Beveridge" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Peter_Loy_Chong", Text = "Não queremos uma teocracia, jamais dissemos que gostaríamos de um Estado cristão. Todavia, estamos preocupados se um Estado laico reduzir a fé a um fato puramente individual.", Author = "Peter Loy Chong" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Hecateu_de_Mileto", Text = "Vou escrever o que acho ser verdade, porque as lendas dos gregos parecem ser muitas e risíveis.", Author = "Hecateu de Mileto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Louise_Nevelson", Text = "Acho que limitar as artes não significa só militar as artes, mas significa limitar a civilização.", Author = "Louise Nevelson" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/James_Payn", Text = "A vingança é um prato que se pode comer frio.", Author = "James Payn" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Z%C3%A9lia_Cardoso_de_Mello", Text = "Zélia executou um plano econômico sem precedentes, abrindo o país para a era das privatizações, importações, modernização industrial e tecnológica.", Author = "Zélia Cardoso de Mello" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luiz_Paulo_Vellozo_Lucas", Text = "Dívida é igual a colesterol, tem a boa e a ruim.", Author = "Luiz Paulo Vellozo Lucas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Robert_Joseph_McManus", Text = "Como bispo diocesano, é meu dever sagrado e minha responsabilidade inerente determinar quando uma escola que se diz 'católica' está agindo contra os ensinamentos da Igreja Católica e ignora minha legítima autoridade como guardião e supervisor da educação católica na diocese de Worcester.", Author = "Robert Joseph McManus" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Segunda_Ep%C3%ADstola_de_Pedro", Text = "Deveis saber, antes de tudo, que nenhuma profecia da Escritura é de interpretação particular, visto que jamais uma profecia foi proferida por vontade humana. Ao contrário, foi sob o impulso do Espírito Santo que alguns falaram da parte de Deus.", Author = "Segunda Epístola de Pedro" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Peter_Stephan_Zurbriggen", Text = "Como Núncio, representante do Santo Padre, estou triste e envergonhado de que quando se coloca cruzes em um país vizinho, seus bispos e sacerdotes pensem que devem criticar a decisão. É uma desgraça! Isso é inaceitável.", Author = "Peter Stephan Zurbriggen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Nando_Carneiro", Text = "Depois de sete anos estudando piano clássico, não pude suportar a rigidez dos métodos aplicados na época. Imediatamente, passei a tocar violão de ouvido, três anos antes de iniciar os estudos de violão clássico.", Author = "Nando Carneiro" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Salvatore_Rumeo", Text = "Precisamos da oração, para poder entrar em um diálogo de amor com o Senhor. A oração é o sopro da alma.", Author = "Salvatore Rumeo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Geraldo_Quint%C3%A3o", Text = "Quintão é uma indicação minha e vai fazer no ministério da Defesa apenas o que eu quiser.", Author = "Geraldo Quintão" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Tarc%C3%ADsio_Nascentes_dos_Santos", Text = "A Igreja vê a conveniência do celibato unido ao sacerdócio por esse amor indiviso. O homem celibatário estaria mais livre para uma dedicação plena e total pelo Reino e pelo povo de Deus. E dedicação total não é só no sentido de tempo, mas no sentido indiviso, para amar mais a Deus.", Author = "Tarcísio Nascentes dos Santos" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Edward_Hiiboro_Kussala", Text = "Enfim, serão a coragem da história completa sobre nós a visão honesta da nossa existência, da nossa história e da nossa realidade nos momentos de altos e baixos, tristes e felizes que trarão a justiça e a paz. Necessitamos quer dos Zaqueus quer dos Bons Samaritanos da Bíblia Sagrada.", Author = "Edward Hiiboro Kussala" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mois%C3%A9s", Text = "E menciona Moisés, no Livro, porque foi leal e foi um mensageiro e um profeta. Chamamo-lo à escarpa direita do Monte e fizemos com que se aproximasse, para uma confidência. E o agraciamos com a Nossa misericórdia, com seu irmão Aarão, outro profeta.", Author = "Moisés" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Josephine_Tey", Text = "Cada um de nós deveria tolerar, em cada um dos outros, três defeitos. Se fizermos essa concessão, verificaremos com surpresa que todas as pessoas são boas.", Author = "Josephine Tey" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Zachary_Taylor", Text = "Por mais de meio século, reinos e impérios caíram, e esta União ficou firme. Os patriotas que formaram a têm muito tempo que desceram à sepultura; mas ainda permanecem, no monumento mais orgulhoso à sua memória.", Author = "Zachary Taylor" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ant%C3%B3nio_Baltasar_Marcelino", Text = "Honra está em ser fiel ao que Deus nos dá e nos pede.", Author = "António Baltasar Marcelino" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Charles_Caleb_Colton", Text = "Os excessos de nossa mocidade são saques sobre a nossa velhice, pagáveis com juros trinta anos depois.", Author = "Charles Caleb Colton" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Sergio_Alfredo_Fenoy", Text = "Quando passar um tempo suficientemente longo e se verificar que esses frutos são bons, são evangélicos, só então há a possibilidade de julgar se o que aconteceu foi algo sobrenatural ou não.", Author = "Sergio Alfredo Fenoy" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Claude_Aveline", Text = "Faz com que cada hora de sua vida seja bela. O menor gesto é uma lembrança futura.", Author = "Claude Aveline" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jo%C3%A3o_Mamede_Filho", Text = "Violência é a que priva pela concentração da propriedade ao não cumprir sua função social. Essa, sim, é violenta e gera famintos e desalentados.", Author = "João Mamede Filho" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Chakaia_Booker", Text = "Minha intenção é traduzir materiais em imagens que estimulem as pessoas a se considerarem como parte de seu ambiente, como uma parte de um todo maior.", Author = "Chakaia Booker" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Pierre_Nora", Text = "A história é reconstrução sempre problemática e incompleta do que não existe mais. A memória um fenômeno sempre atual, um elo vivido no eterno presente; a história, uma representação do passado.", Author = "Pierre Nora" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Marcela_Fern%C3%A1ndez", Text = "As geleiras me ensinaram a lidar com o luto, com a ausência. Quando você as ouve, sabe que a perda delas é um dano que não podemos desfazer, mas ainda assim podemos contribuir e deixar uma marca.- Fonte: BBC", Author = "Marcela Fernández" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Calvin_Coolidge", Text = "A publicidade é a vida do comércio.", Author = "Calvin Coolidge" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Richard_Kuuia_Baawobr", Text = "Acredito que cada um de nós, onde quer que estejamos, é chamado a servir, e é isso que nos fará grandes, não o título.", Author = "Richard Kuuia Baawobr" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Germano_Grachane", Text = "É uma crítica fácil dizer que a Igreja Católica se identifica com a política, particularmente, com o regime colonial. Prontos, aceitamos a crítica, mas não é verdade, porque, se não fosse a igreja, o colonialismo teria sido mil vezes mais cruel do que foi.", Author = "Germano Grachane" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ana_Carolina_Reston", Text = "Muitas meninas dão mais importância ao trabalho e a certos ideais de beleza do que à saúde. É um erro. Sempre me alimentei bem. Não abuso, mas jamais passaria fome por causa de um trabalho.", Author = "Ana Carolina Reston" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Roberto_Rodrigues", Text = "Eu mandei o vagabundo do Guido Mantega para a PQP", Author = "Roberto Rodrigues" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Madeleine_L%27Engle", Text = "É a capacidade de escolher que faz de nós seres humanos.", Author = "Madeleine L'Engle" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mansur_al-Hallaj", Text = "Eu vi o meu Senhor com o olho de meu do coração. Ele disse: Quem é você?, Eu sou tu. Tue és Aquele que preenche todo o lugar mas o lugar não sabe onde Tu estás. Em minha substância, és minha aniquilação; E na minha aniquilação, eu permaneço Tu.", Author = "Mansur al-Hallaj" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jorge_Ferreira_da_Costa_Ortiga", Text = "O ir ao encontro de Cristo nos necessitados através duma dedicação total deve ter uma dimensão universal que não premite acepção de pessoas mesmo por motivos religiosos. Partir é sinónimo de coragem e nunca admite cansaços. Só assim a civilização do amor se irá concretizando.", Author = "Jorge Ferreira da Costa Ortiga" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Lawrence_Daniel_Huculak", Text = "A restauração da estátua é uma das prioridades.", Author = "Lawrence Daniel Huculak" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Elias_Chacour", Text = "Primavera árabe é um nome errado, não foi uma primavera, mas um oceânico derramamento de sangue. Muitos foram os mortos, mas aqueles que mais perderam foram os cristãos", Author = "Elias Chacour" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Claude_Dagens", Text = "Quanto aos responsáveis da Igreja Católica na França, com os quais eu sou solidário, eles estariam mal inspirados se tentassem pegar o trem das ondas políticas andando, tentando agradar os ultra e os outros. Se esse oportunismo levasse a melhor, em alguns anos pagaríamos o preço.", Author = "Claude Dagens" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Alberto_Braga", Text = "A José Alberto Braga (JAAB) não lhe falta nenhuma das qualidades cívicas essenciais ao humorista", Author = "José Alberto Braga" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Laura_Loomer", Text = "Eles deveriam receber a pena de morte. Você sabe, nós realmente costumávamos ter, a punição por traição neste país.", Author = "Laura Loomer" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Billy_Blanco", Text = "A cidade não desperta", Author = "Billy Blanco" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ludger_Schepers", Text = "Deve ficar claro que os valores tradicionais, como a responsabilidade numa parceria e a fiabilidade, são neutros em termos de gênero.", Author = "Ludger Schepers" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Emma_Goldman", Text = "Se eu não puder dançar, não quero ser parte de sua revolução!", Author = "Emma Goldman" }
    };
}